export const gotterdammerungAct3Scenes = [{"number":2,"originalHeading":"ZWEITE SZENE","translatedHeading":"Second Scene","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Wildes Wald- und Felsental am Rheine, welcher im Hintergrunde an einem steilen Abhange vorbeifliesst","translatedTitle":"Wild forest and rocky valley on the Rhine, which flows past a steep slope in the background.","participants":[],"sourceStartIndex":0,"sourceLineCount":1,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Wildes Wald- und Felsental am Rheine, welcher im Hintergrunde an einem steilen Abhange vorbeifliesst","translation":"Wild forest and rocky valley on the Rhine, which flows past a steep slope in the background.","literalText":true,"sourceStartIndex":0,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Frau Sonne sendet lichte Strahlen;","translatedTitle":"Lady Sun sends out bright rays;","participants":["DIE DREI RHEINTÖCHTER","WOGLINDE","WELLGUNDE","FLOSSHILDE","SIEGFRIED","ALLE DREI"],"sourceStartIndex":1,"sourceLineCount":75,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Die drei Rheintöchter, Siegfried. Die drei Rheintöchter, Woglinde, Wellgunde und Flosshilde, tauchen aus der Flut auf und schwimmen, wie im Reigentanze, im Kreise umher\nim Schwimmen mässig einhaltend","translation":"The three Rhine maidens, Siegfried. The three Rhine maidens, Woglinde, Wellgunde, and Flosshilde, emerge from the flood and swim around in a circle, as if in a round dance.\nmoderately obeying the rules while swimming","literalText":true,"sourceStartIndex":0,"sourceLineCount":2},{"speaker":"DIE DREI RHEINTÖCHTER","speakerTranslation":"DIE DREI RHEINTÖCHTER","original":"Frau Sonne sendet lichte Strahlen;\nNacht liegt in der Tiefe:\neinst war sie hell,\nda heil und hehr\ndes Vaters Gold noch in ihr glänzte.\nRheingold! Klares Gold!\nWie hell du einstens strahltest,\nhehrer Stern der Tiefe!","translation":"Lady Sun sends out bright rays;\nNight lies deep:\nOnce it was bright,\nthere, holy and sublime\nHer father's gold still shone within her.\nRhine gold! Clear gold!\nHow brightly you once shone,\nsublime star of the deep!","literalText":true,"sourceStartIndex":2,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie schliessen wieder den Schwimmreigen","translation":"They bring the swimming round to a close.","literalText":true,"sourceStartIndex":10,"sourceLineCount":1},{"speaker":"DIE DREI RHEINTÖCHTER","speakerTranslation":"DIE DREI RHEINTÖCHTER","original":"Weialala leia, wallala leialala.","translation":"Weialala leia, wallala leialala.","literalText":true,"sourceStartIndex":11,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Ferner Hornruf. Sie lauschen. Sie schlagen jauchzend das Wasser","translation":"A distant horn call. They listen. They thump the water with shouts of joy.","literalText":true,"sourceStartIndex":12,"sourceLineCount":1},{"speaker":"DIE DREI RHEINTÖCHTER","speakerTranslation":"DIE DREI RHEINTÖCHTER","original":"Frau Sonne, sende uns den Helden,\nder das Gold uns wiedergäbe!\nLiess' er es uns, dein lichtes Auge\nneideten dann wir nicht länger.\nRheingold! Klares Gold!\nWie froh du dann strahltest,\nfreier Stern der Tiefe!","translation":"Ms. Sun, send us the hero,\nwho would give us back the gold!\nDid he let us see it, your bright eye?\nWe were no longer envious.\nRhine gold! Clear gold!\nHow happily you beamed then,\nFree star of the deep!","literalText":true,"sourceStartIndex":13,"sourceLineCount":7},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Man hört Siegfrieds Horn von der Höhe her","translation":"Siegfried's horn can be heard from the heights.","literalText":true,"sourceStartIndex":20,"sourceLineCount":1},{"speaker":"WOGLINDE","speakerTranslation":"WOGLINDE","original":"Ich höre sein Horn.","translation":"I hear his horn.","literalText":true,"sourceStartIndex":21,"sourceLineCount":1},{"speaker":"WELLGUNDE","speakerTranslation":"WELLGUNDE","original":"Der Helde naht.","translation":"The hero is approaching.","literalText":true,"sourceStartIndex":22,"sourceLineCount":1},{"speaker":"FLOSSHILDE","speakerTranslation":"FLOSSHILDE","original":"Lasst uns beraten!","translation":"Let's have a consultation!","literalText":true,"sourceStartIndex":23,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie tauchen alle drei schnell unter. Siegfried erscheint auf dem Abhange in vollen Waffen","translation":"All three quickly submerge. Siegfried reappears on the slope fully armed.","literalText":true,"sourceStartIndex":24,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Ein Albe führte mich irr,\ndass ich die Fährte verlor:\nHe, Schelm, in welchem Berge\nbargst du so schnell mir das Wild?","translation":"An elf led me astray,\nthat I lost the trail:\nHey, rascal, in which mountain\nDid you retrieve the game for me so quickly?","literalText":true,"sourceStartIndex":25,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"tauchen wieder auf und schwimmen im Reigen","translation":"They reappear and swim in a circle.","literalText":true,"sourceStartIndex":29,"sourceLineCount":1},{"speaker":"DIE DREI RHEINTÖCHTER","speakerTranslation":"DIE DREI RHEINTÖCHTER","original":"Siegfried!","translation":"Siegfried!","literalText":true,"sourceStartIndex":30,"sourceLineCount":1},{"speaker":"FLOSSHILDE","speakerTranslation":"FLOSSHILDE","original":"Was schiltst du so in den Grund?","translation":"What are you scolding so harshly?","literalText":true,"sourceStartIndex":31,"sourceLineCount":1},{"speaker":"WELLGUNDE","speakerTranslation":"WELLGUNDE","original":"Welchem Alben bist du gram?","translation":"Which album are you angry with?","literalText":true,"sourceStartIndex":32,"sourceLineCount":1},{"speaker":"WOGLINDE","speakerTranslation":"WOGLINDE","original":"Hat dich ein Nicker geneckt?","translation":"Did a nap tease you?","literalText":true,"sourceStartIndex":33,"sourceLineCount":1},{"speaker":"ALLE DREI","speakerTranslation":"ALLE DREI","original":"Sag' es, Siegfried, sag' es uns!","translation":"Tell us, Siegfried, tell us!","literalText":true,"sourceStartIndex":34,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"sie lächelnd betrachtend","translation":"looking at her, smiling","literalText":true,"sourceStartIndex":35,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Entzücktet ihr zu euch den zottigen Gesellen,\nder mir verschwand?\nIst's euer Friedel,\neuch lustigen Frauen lass' ich ihn gern.","translation":"Did you delight in the shaggy fellow?\nwho disappeared from me?\nIs this your Friedel?\nI'll gladly let you funny women have him.","literalText":true,"sourceStartIndex":36,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Die Mädchen lachen laut auf","translation":"The girls laughed loudly","literalText":true,"sourceStartIndex":40,"sourceLineCount":1},{"speaker":"WOGLINDE","speakerTranslation":"WOGLINDE","original":"Siegfried, was gibst du uns,\nwenn wir das Wild dir gönnen?","translation":"Siegfried, what will you give us?\nIf we allow you to have the game?","literalText":true,"sourceStartIndex":41,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Noch bin ich beutelos;\nso bittet, was ihr begehrt.","translation":"I'm still bagless;\nSo ask for what you desire.","literalText":true,"sourceStartIndex":43,"sourceLineCount":2},{"speaker":"WELLGUNDE","speakerTranslation":"WELLGUNDE","original":"Ein goldner Ring ragt dir am Finger!","translation":"A golden ring hangs from your finger!","literalText":true,"sourceStartIndex":45,"sourceLineCount":1},{"speaker":"DIE DREI RHEINTÖCHTER","speakerTranslation":"DIE DREI RHEINTÖCHTER","original":"Den gib uns!","translation":"Give it to us!","literalText":true,"sourceStartIndex":46,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Einen Riesenwurm erschlug ich um den Reif:\nfür eines schlechten Bären Tatzen\nböt' ich ihn nun zum Tausch?","translation":"I killed a giant worm around the frost:\nfor a bad bear's paws\nWould I offer him in exchange?","literalText":true,"sourceStartIndex":47,"sourceLineCount":3},{"speaker":"WOGLINDE","speakerTranslation":"WOGLINDE","original":"Bist du so karg?","translation":"Are you so stingy?","literalText":true,"sourceStartIndex":50,"sourceLineCount":1},{"speaker":"WELLGUNDE","speakerTranslation":"WELLGUNDE","original":"So geizig beim Kauf?","translation":"So stingy when buying things?","literalText":true,"sourceStartIndex":51,"sourceLineCount":1},{"speaker":"FLOSSHILDE","speakerTranslation":"FLOSSHILDE","original":"Freigebig solltest Frauen du sein.","translation":"Women should be generous.","literalText":true,"sourceStartIndex":52,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Verzehrt' ich an euch mein Gut,\ndes zürnte mir wohl mein Weib.","translation":"If I consumed my wealth on you,\nMy wife was probably angry with me for that.","literalText":true,"sourceStartIndex":53,"sourceLineCount":2},{"speaker":"FLOSSHILDE","speakerTranslation":"FLOSSHILDE","original":"Sie ist wohl schlimm?","translation":"Is she really bad?","literalText":true,"sourceStartIndex":55,"sourceLineCount":1},{"speaker":"WELLGUNDE","speakerTranslation":"WELLGUNDE","original":"Sie schlägt dich wohl?","translation":"She probably hits you?","literalText":true,"sourceStartIndex":56,"sourceLineCount":1},{"speaker":"WOGLINDE","speakerTranslation":"WOGLINDE","original":"Ihre Hand fühlt schon der Held!","translation":"The hero already feels her hand!","literalText":true,"sourceStartIndex":57,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie lachen unmässig","translation":"They laugh uncontrollably","literalText":true,"sourceStartIndex":58,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Nun lacht nur lustig zu!\nIn Harm lass' ich euch doch:\ndenn giert ihr nach dem Ring,\neuch Nickern geb' ich ihn nie!","translation":"Now just laugh merrily!\nI will leave you in harm:\nfor do you yearn for the ring,\nI'll never give it to you noobs!","literalText":true,"sourceStartIndex":59,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Die Rheintöchter haben sich wieder zum Reigen gefasst","translation":"The Rhine maidens have resumed their dance.","literalText":true,"sourceStartIndex":63,"sourceLineCount":1},{"speaker":"FLOSSHILDE","speakerTranslation":"FLOSSHILDE","original":"So schön!","translation":"So beautiful!","literalText":true,"sourceStartIndex":64,"sourceLineCount":1},{"speaker":"WELLGUNDE","speakerTranslation":"WELLGUNDE","original":"So stark!","translation":"So powerful!","literalText":true,"sourceStartIndex":65,"sourceLineCount":1},{"speaker":"WOGLINDE","speakerTranslation":"WOGLINDE","original":"So gehrenswert!","translation":"How admirable!","literalText":true,"sourceStartIndex":66,"sourceLineCount":1},{"speaker":"ALLE DREI","speakerTranslation":"ALLE DREI","original":"Wie schade, dass er geizig ist!","translation":"What a shame that he's stingy!","literalText":true,"sourceStartIndex":67,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie lachen und tauchen unter\ntiefer in den Grund hinabsteigend","translation":"They laugh and dive under.\ndescending deeper into the ground","literalText":true,"sourceStartIndex":68,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Was leid' ich doch das karge Lob?\nLass' ich so mich schmähn?\nKämen sie wieder zum Wasserrand,\nden Ring könnten sie haben.","translation":"How I suffer the meager praise!\nWill I allow myself to be insulted like this?\nIf they returned to the water's edge,\nThey could have the ring.","literalText":true,"sourceStartIndex":70,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"laut rufend","translation":"shouting loudly","literalText":true,"sourceStartIndex":74,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"He! He, he! Ihr muntren Wasserminnen!","translatedTitle":"Hey! Hey, he! You merry water mints!","participants":["SIEGFRIED","FLOSSHILDE","WOGLINDE UND WELLGUNDE","ALLE DREI","DIE RHEINTÖCHTER","WELLGUNDE","WELLGUNDE UND FLOSSHILDE","DIE DREI RHEINTÖCHTER","FLOSSHILDE, DANN WOGLINDE"],"sourceStartIndex":76,"sourceLineCount":70,"turns":[{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"He! He, he! Ihr muntren Wasserminnen!\nKommt rasch! Ich schenk' euch den Ring!","translation":"Hey! Hey, he! You merry water mints!\nCome quickly! I'll give you the ring!","literalText":true,"sourceStartIndex":75,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er hat den Ring vom Finger gezogen und hält ihn in die Höhe. Die drei Rheintöchter tauchen wieder auf. Sie zeigen sich ernst und feierlich","translation":"He pulled the ring from his finger and held it aloft. The three Rhine maidens reappeared. They appeared solemn and grave.","literalText":true,"sourceStartIndex":77,"sourceLineCount":1},{"speaker":"FLOSSHILDE","speakerTranslation":"FLOSSHILDE","original":"Behalt' ihn, Held, und wahr' ihn wohl,\nbis du das Unheil errätst -","translation":"Keep him, hero, and cherish him well,\nuntil you guess the disaster -","literalText":true,"sourceStartIndex":78,"sourceLineCount":2},{"speaker":"WOGLINDE UND WELLGUNDE","speakerTranslation":"WOGLINDE UND WELLGUNDE","original":"das in dem Ring du hegst.","translation":"that which you harbor in the ring.","literalText":true,"sourceStartIndex":80,"sourceLineCount":1},{"speaker":"ALLE DREI","speakerTranslation":"ALLE DREI","original":"Froh fühlst du dich dann,\nbefrein wir dich von dem Fluch.","translation":"You feel happy then,\nWe will free you from the curse.","literalText":true,"sourceStartIndex":81,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"steckt gelassen den Ring wieder an seinen Finger","translation":"Calmly, he slipped the ring back onto his finger.","literalText":true,"sourceStartIndex":83,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"So singet, was ihr wisst!","translation":"So sing what you know!","literalText":true,"sourceStartIndex":84,"sourceLineCount":1},{"speaker":"DIE RHEINTÖCHTER","speakerTranslation":"DIE RHEINTÖCHTER","original":"Siegfried! Siegfried! Siegfried!\nSchlimmes wissen wir dir.","translation":"Siegfried! Siegfried! Siegfried!\nWe know the bad things are happening to you.","literalText":true,"sourceStartIndex":85,"sourceLineCount":2},{"speaker":"WELLGUNDE","speakerTranslation":"WELLGUNDE","original":"Zu deinem Unheil wahrst du den Reif!","translation":"To your misfortune, you preserved the frost!","literalText":true,"sourceStartIndex":87,"sourceLineCount":1},{"speaker":"ALLE DREI","speakerTranslation":"ALLE DREI","original":"Aus des Rheines Gold ist der Reif geglüht.","translation":"The rim glowed from the Rhine's gold.","literalText":true,"sourceStartIndex":88,"sourceLineCount":1},{"speaker":"WELLGUNDE","speakerTranslation":"WELLGUNDE","original":"Der ihn listig geschmiedet und schmählich verlor -","translation":"He who cunningly forged him and lost him shamefully -","literalText":true,"sourceStartIndex":89,"sourceLineCount":1},{"speaker":"ALLE DREI","speakerTranslation":"ALLE DREI","original":"der verfluchte ihn, in fernster Zeit\nzu zeugen den Tod dem, der ihn trüg'.","translation":"he cursed him, in the distant past\nto bear witness to the death of him who bore him.","literalText":true,"sourceStartIndex":90,"sourceLineCount":2},{"speaker":"FLOSSHILDE","speakerTranslation":"FLOSSHILDE","original":"Wie den Wurm du fälltest -","translation":"How you fell the worm -","literalText":true,"sourceStartIndex":92,"sourceLineCount":1},{"speaker":"WELLGUNDE UND FLOSSHILDE","speakerTranslation":"WELLGUNDE UND FLOSSHILDE","original":"so fällst auch du -","translation":"so you too will fall -","literalText":true,"sourceStartIndex":93,"sourceLineCount":1},{"speaker":"ALLE DREI","speakerTranslation":"ALLE DREI","original":"und heute noch:\nSo heissen wir's dir,\ntauschest den Ring du uns nicht -","translation":"and even today:\nThat's how we'll tell you,\nYou won't exchange the ring with us -","literalText":true,"sourceStartIndex":94,"sourceLineCount":3},{"speaker":"WELLGUNDE UND FLOSSHILDE","speakerTranslation":"WELLGUNDE UND FLOSSHILDE","original":"im tiefen Rhein ihn zu bergen:","translation":"to recover him from the deep Rhine:","literalText":true,"sourceStartIndex":97,"sourceLineCount":1},{"speaker":"ALLE DREI","speakerTranslation":"ALLE DREI","original":"Nur seine Flut sühnet den Fluch!","translation":"Only its flood can atone for the curse!","literalText":true,"sourceStartIndex":98,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Ihr listigen Frauen, lasst das sein!\nTraut' ich kaum eurem Schmeicheln,\neuer Drohen schreckt mich noch minder!","translation":"You cunning women, stop it!\nI could hardly trust your flattery,\nYour threats scare me even less!","literalText":true,"sourceStartIndex":99,"sourceLineCount":3},{"speaker":"DIE DREI RHEINTÖCHTER","speakerTranslation":"DIE DREI RHEINTÖCHTER","original":"Siegfried! Siegfried!\nWir weisen dich wahr.\nWeiche, weiche dem Fluch!\nIhn flochten nächtlich webende Nornen\nin des Urgesetzes Seil!","translation":"Siegfried! Siegfried!\nWe make you true.\nYield, yield to the curse!\nIt was woven by the Norns, who wove at night.\nin the rope of the original law!","literalText":true,"sourceStartIndex":102,"sourceLineCount":5},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Mein Schwert zerschwang einen Speer:\ndes Urgesetzes ewiges Seil,\nflochten sie wilde Flüche hinein,\nNotung zerhaut es den Nornen!\nWohl warnte mich einst\nvor dem Fluch ein Wurm,\ndoch das Fürchten lehrt' er mich nicht!","translation":"My sword shattered a spear:\neternal rope of the original law,\nThey wove in wild curses,\nNothung is destroying the Norns!\nI was once warned by...\nA worm before the curse,\nBut he does not teach me to be afraid!","literalText":true,"sourceStartIndex":107,"sourceLineCount":7},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er betrachtet den Ring","translation":"He looks at the ring","literalText":true,"sourceStartIndex":114,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Der Welt Erbe gewänne mir ein Ring:\nfür der Minne Gunst miss' ich ihn gern;\nich geb' ihn euch, gönnt ihr mir Lust.\nDoch bedroht ihr mir Leben und Leib:\nfasste er nicht eines Fingers Wert,\nden Reif entringt ihr mir nicht!\nDenn Leben und Leib,\nseht: - so - werf' ich sie weit von mir!","translation":"The world's inheritance would win me a ring:\nFor the favor of love I would gladly miss him;\nI'll give it to you, if you grant me pleasure.\nBut you threaten my life and limb:\nHe didn't value a finger in the eye,\nYou will not wrest the frost from me!\nFor life and body,\nLook: - like this - I'll throw them far away from me!","literalText":true,"sourceStartIndex":115,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er hebt eine Erdscholle vom Boden auf, hält sie über seinem Haupte und wirft sie mit den letzten Worten hinter sich","translation":"He picks up a clod of earth from the ground, holds it above his head, and throws it behind him with his last words.","literalText":true,"sourceStartIndex":123,"sourceLineCount":1},{"speaker":"DIE DREI RHEINTÖCHTER","speakerTranslation":"DIE DREI RHEINTÖCHTER","original":"Kommt, Schwestern!\nSchwindet dem Toren!\nSo weise und stark verwähnt sich der Held,\nals gebunden und blind er doch ist.","translation":"Come, sisters!\nVanish, fool!\nThe hero imagines himself to be so wise and strong,\nas though he is bound and blind.","literalText":true,"sourceStartIndex":124,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie schwimmen, wild aufgeregt, in weiten Schwenkungen dicht an das Ufer heran","translation":"They swim, wildly excited, in wide swerves close to the shore.","literalText":true,"sourceStartIndex":128,"sourceLineCount":1},{"speaker":"DIE DREI RHEINTÖCHTER","speakerTranslation":"DIE DREI RHEINTÖCHTER","original":"Eide schwur er - und achtet sie nicht.","translation":"He swore oaths - and yet he did not heed them.","literalText":true,"sourceStartIndex":129,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Wieder heftige Bewegung","translation":"More violent movement","literalText":true,"sourceStartIndex":130,"sourceLineCount":1},{"speaker":"DIE DREI RHEINTÖCHTER","speakerTranslation":"DIE DREI RHEINTÖCHTER","original":"Runen weiss er - und rät sie nicht!","translation":"He knows about runes - and he doesn't advise them!","literalText":true,"sourceStartIndex":131,"sourceLineCount":1},{"speaker":"FLOSSHILDE, DANN WOGLINDE","speakerTranslation":"FLOSSHILDE, DANN WOGLINDE","original":"Ein hehrstes Gut ward ihm vergönnt.","translation":"He was granted one of the greatest treasures.","literalText":true,"sourceStartIndex":132,"sourceLineCount":1},{"speaker":"ALLE DREI","speakerTranslation":"ALLE DREI","original":"Dass er's verworfen, weiss er nicht;","translation":"He doesn't know that he rejected it;","literalText":true,"sourceStartIndex":133,"sourceLineCount":1},{"speaker":"FLOSSHILDE","speakerTranslation":"FLOSSHILDE","original":"nur den Ring, -","translation":"just the ring, -","literalText":true,"sourceStartIndex":134,"sourceLineCount":1},{"speaker":"WELLGUNDE","speakerTranslation":"WELLGUNDE","original":"der zum Tod ihm taugt, -","translation":"who is suitable for his death, -","literalText":true,"sourceStartIndex":135,"sourceLineCount":1},{"speaker":"ALLE DREI","speakerTranslation":"ALLE DREI","original":"den Reif nur will er sich wahren!\nLeb' wohl, Siegfried!\nEin stolzes Weib\nwird noch heute dich Argen beerben:\nsie beut uns besseres Gehör:\nZu ihr! Zu ihr! Zu ihr!","translation":"He only wants to preserve the frost!\nFarewell, Siegfried!\nA proud woman\nArgen will inherit yours today:\nIt gives us better hearing:\nGo to her! Go to her! Go to her!","literalText":true,"sourceStartIndex":136,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie wenden sich schnell zum Reigen, mit welchem sie gemächlich dem Hintergrunde zu fortschwimmen.\nSiegfried sieht ihnen lächelnd nach, stemmt ein Bein auf ein Felsstück am Ufer und verweilt mit auf der Hand gestütztem Kinne","translation":"They quickly turn to the dance, with which they leisurely swim away towards the background.\nSiegfried watches them with a smile, braces one leg on a rock on the shore, and lingers with his chin resting on his hand.","literalText":true,"sourceStartIndex":142,"sourceLineCount":2},{"speaker":"ALLE DREI","speakerTranslation":"ALLE DREI","original":"Weialala leia, wallala leialala.","translation":"Weialala leia, wallala leialala.","literalText":true,"sourceStartIndex":144,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Im Wasser, wie am Lande","translatedTitle":"In the water, as on land","participants":["SIEGFRIED","DIE RHEINTÖCHTER"],"sourceStartIndex":146,"sourceLineCount":14,"turns":[{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Im Wasser, wie am Lande\nlernte nun ich Weiberart:\nwer nicht ihrem Schmeicheln traut,\nden schrecken sie mit Drohen;\nwer dem kühnlich trotzt,\ndem kommt dann ihr Keifen dran.","translation":"In the water, as on land\nI now learned about women's manners:\nthose who do not trust her flattery,\nThey frighten him with threats;\nwho boldly defies it,\nThen it's her turn to yell.","literalText":true,"sourceStartIndex":145,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Die Rheintöchter sind hier gänzlich verschwunden","translation":"The Rhine maidens have completely disappeared here.","literalText":true,"sourceStartIndex":151,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Und doch, trüg' ich nicht Gutrun' Treu, -\nder zieren Frauen eine\nhätt' ich mir frisch gezähmt!","translation":"And yet, I would not betray Gutrun's loyalty, -\nthe women adorn a\nI would have tamed it myself!","literalText":true,"sourceStartIndex":152,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er blickt ihnen unverwandt nach\nin grösserer Entfernung","translation":"He stares intently after them.\nat a greater distance","literalText":true,"sourceStartIndex":155,"sourceLineCount":2},{"speaker":"DIE RHEINTÖCHTER","speakerTranslation":"DIE RHEINTÖCHTER","original":"La, la!","translation":"La, la!","literalText":true,"sourceStartIndex":157,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Jagdhornrufe kommen von der Höhe näher","translation":"Hunting horn calls are coming closer from the heights.","literalText":true,"sourceStartIndex":158,"sourceLineCount":1}]}]},{"number":3,"originalHeading":"ZWEITE SZENE","translatedHeading":"Third Scene","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Hoiho!","translatedTitle":"Hoiho!","participants":["HAGENS STIMME","DIE MANNEN","SIEGFRIED","HAGEN","GUNTHER"],"sourceStartIndex":0,"sourceLineCount":72,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"von fern","translation":"from afar","literalText":true,"sourceStartIndex":0,"sourceLineCount":1},{"speaker":"HAGENS STIMME","speakerTranslation":"HAGENS STIMME","original":"Hoiho!\nSiegfried fährt aus seiner träumerischen Entrücktheit auf und antwortet dem vernommenen Rufe auf seinem Horne","translation":"Hoiho!\nSiegfried jolts awake from his dreamy reverie and answers the heard call on his horn.","literalText":true,"sourceStartIndex":1,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"ausserhalb der Szene","translation":"outside the scene","literalText":true,"sourceStartIndex":3,"sourceLineCount":1},{"speaker":"DIE MANNEN","speakerTranslation":"DIE MANNEN","original":"Hoiho! Hoiho!","translation":"Hoiho! Hoiho!","literalText":true,"sourceStartIndex":4,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"antwortend","translation":"responding","literalText":true,"sourceStartIndex":5,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Hoiho! Hoiho! Hoihe!","translation":"Hoiho! Hoiho! Hoihe!","literalText":true,"sourceStartIndex":6,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"kommt auf der Höhe hervor. Gunther folgt ihm. Siegfried erblickend","translation":"He emerges from the hilltop. Gunther follows him. Siegfried sees him.","literalText":true,"sourceStartIndex":7,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Finden wir endlich,\nwohin du flogest?","translation":"Let's finally find...\nWhere did you fly to?","literalText":true,"sourceStartIndex":8,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Kommt herab! Hier ist's frisch und kühl!","translation":"Come down! It's fresh and cool here!","literalText":true,"sourceStartIndex":10,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Die Mannen kommen alle auf der Höhe an und steigen nun mit Hagen und Gunther herab","translation":"The men all arrive at the summit and now descend with Hagen and Gunther.","literalText":true,"sourceStartIndex":11,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Hier rasten wir und rüsten das Mahl.","translation":"Here we rest and prepare the meal.","literalText":true,"sourceStartIndex":12,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Jagdbeute wird zuhauf gelegt","translation":"Hunted prey is laid out in abundance.","literalText":true,"sourceStartIndex":13,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Lasst ruhn die Beute und bietet die Schläuche!","translation":"Let the prey rest and offer the hoses!","literalText":true,"sourceStartIndex":14,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Trinkhörner und Schläuche werden hervorgeholt, dann lagert sich alles","translation":"Drinking horns and hoses are brought out, then everything is stored away.","literalText":true,"sourceStartIndex":15,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Der uns das Wild verscheuchte,\nnun sollt ihr Wunder hören,\nwas Siegfried sich erjagt.","translation":"The one who scared away the game,\nNow you shall hear of wonders,\nwhat Siegfried hunted down.","literalText":true,"sourceStartIndex":16,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"lachend","translation":"laughing","literalText":true,"sourceStartIndex":19,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Schlimm steht es um mein Mahl:\nvon eurer Beute bitte ich für mich.","translation":"My meal is in dire straits:\nI ask for some of your loot for myself.","literalText":true,"sourceStartIndex":20,"sourceLineCount":2},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Du beutelos?","translation":"Are you bagless?","literalText":true,"sourceStartIndex":22,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Auf Waldjagd zog ich aus,\ndoch Wasserwild zeigte sich nur.\nWar ich dazu recht beraten,\ndrei wilde Wasservögel\nhätt' ich euch wohl gefangen,\ndie dort auf dem Rheine mir sangen,\nerschlagen würd' ich noch heut'.","translation":"I went out hunting in the woods,\nBut only waterfowl were visible.\nWas I right to do that?\nthree wild water birds\nI would probably have caught you,\nwho sang to me there on the Rhine,\nI'd be killed today.","literalText":true,"sourceStartIndex":23,"sourceLineCount":7},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er lagert sich zwischen Gunther und Hagen. Gunther erschrickt und blickt düster auf Hagen","translation":"He positions himself between Gunther and Hagen. Gunther is startled and glares darkly at Hagen.","literalText":true,"sourceStartIndex":30,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Das wäre üble Jagd,\nwenn den Beutelosen selbst\nein lauernd Wild erlegte!","translation":"That would be a nasty hunt,\nwhen the lootless themselves\nHe killed a lurking wild animal!","literalText":true,"sourceStartIndex":31,"sourceLineCount":3},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Mich dürstet!","translation":"I am thirsty!","literalText":true,"sourceStartIndex":34,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"indem er für Siegfried ein Trinkhorn füllen lässt und es diesem dann darreicht","translation":"by having a drinking horn filled for Siegfried and then presenting it to him.","literalText":true,"sourceStartIndex":35,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Ich hörte sagen, Siegfried,\nder Vögel Sangessprache\nverstündest du wohl:\nso wäre das wahr?","translation":"I heard Siegfried say,\nthe song language of birds\nYou would probably understand:\nWould that be true?","literalText":true,"sourceStartIndex":36,"sourceLineCount":4},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Seit lange acht' ich des Lallens nicht mehr.","translation":"I haven't paid attention to babbling for a long time.","literalText":true,"sourceStartIndex":40,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er fasst das Trinkhorn und wendet sich damit zu Gunther. Er trinkt und reicht das Horn Gunther hin","translation":"He grasps the drinking horn and turns to Gunther. He drinks and hands the horn to Gunther.","literalText":true,"sourceStartIndex":41,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Trink', Gunther, trink'!\nDein Bruder bringt es dir!","translation":"Drink, Gunther, drink!\nYour brother will bring it to you!","literalText":true,"sourceStartIndex":42,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"gedankenvoll und schwermütig in das Horn blickend, dumpf","translation":"Gazing thoughtfully and melancholy into the horn, dully","literalText":true,"sourceStartIndex":44,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Du mischtest matt und bleich:","translation":"You mixed matte and pale:","literalText":true,"sourceStartIndex":45,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"noch gedämpfter","translation":"even more subdued","literalText":true,"sourceStartIndex":46,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"dein Blut allein darin!","translation":"Your blood alone in it!","literalText":true,"sourceStartIndex":47,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"lachend","translation":"laughing","literalText":true,"sourceStartIndex":48,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"So misch' ich's mit dem deinen!","translation":"So I'll mix it with yours!","literalText":true,"sourceStartIndex":49,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er giesst aus Gunthers Horn in das seine, so dass dieses überläuft","translation":"He pours from Gunther's horn into his own, so that it overflows.","literalText":true,"sourceStartIndex":50,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Nun floss gemischt es über:\nder Mutter Erde lass das ein Labsal sein!","translation":"Now, mixed together, it flowed over:\nMay this be a balm to Mother Earth!","literalText":true,"sourceStartIndex":51,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"mit einem heftigen Seufzer","translation":"with a heavy sigh","literalText":true,"sourceStartIndex":53,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Du überfroher Held!","translation":"You overjoyed hero!","literalText":true,"sourceStartIndex":54,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"leise zu Hagen","translation":"quietly to Hagen","literalText":true,"sourceStartIndex":55,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Ihm macht Brünnhilde Müh?","translation":"Is Brünnhilde causing him trouble?","literalText":true,"sourceStartIndex":56,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"leise zu Siegfried","translation":"quietly to Siegfried","literalText":true,"sourceStartIndex":57,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Verstünd' er sie so gut,\nwie du der Vögel Sang!","translation":"If he understood her so well,\nHow you, the birds, sang!","literalText":true,"sourceStartIndex":58,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Seit Frauen ich singen hörte,\nvergass ich der Vöglein ganz.","translation":"Since I first heard women sing,\nI completely forgot about the little birds.","literalText":true,"sourceStartIndex":60,"sourceLineCount":2},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Doch einst vernahmst du sie?","translation":"But once you heard them?","literalText":true,"sourceStartIndex":62,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"sich lebhaft zu Gunther wendend","translation":"turning animatedly to Gunther","literalText":true,"sourceStartIndex":63,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Hei! Gunther, grämlicher Mann!\nDankst du es mir,\nso sing' ich dir Mären\naus meinen jungen Tagen.","translation":"Hey! Gunther, you grumpy man!\nWill you thank me?\nSo I'll sing you tales\nfrom my younger days.","literalText":true,"sourceStartIndex":64,"sourceLineCount":4},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Die hör' ich so gern.","translation":"I love listening to them.","literalText":true,"sourceStartIndex":68,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Alle lagern sich nah an Siegfried, welcher allein aufrecht sitzt, während die andern tiefer gestreckt liegen","translation":"They all lie close to Siegfried, who alone sits upright, while the others lie stretched out lower down.","literalText":true,"sourceStartIndex":69,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":".","translation":".","literalText":true,"sourceStartIndex":70,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"So singe, Held!","translation":"Sing, hero!","literalText":true,"sourceStartIndex":71,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Mime hiess ein mürrischer Zwerg:","translatedTitle":"Mime was the name of a grumpy dwarf:","participants":["SIEGFRIED","HAGEN","DIE MANNEN","VIER MANNEN","ZWEI MANNEN"],"sourceStartIndex":72,"sourceLineCount":73,"turns":[{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Mime hiess ein mürrischer Zwerg:\nin des Neides Zwang zog er mich auf,\ndass einst das Kind, wann kühn es erwuchs,\neinen Wurm ihm fällt' im Wald,\nder faul dort hütet' einen Hort.\nEr lehrte mich schmieden und Erze schmelzen;\ndoch was der Künstler selber nicht konnt',\ndes Lehrlings Mute musst' es gelingen:\neines zerschlagnen Stahles Stücke\nneu zu schmieden zum Schwert.\nDes Vaters Wehr fügt' ich mir neu:\nnagelfest schuf ich mir Notung.\nTüchtig zum Kampf dünkt' er dem Zwerg;\nder führte mich nun zum Wald:\ndort fällt' ich Fafner, den Wurm.\nJetzt aber merkt wohl auf die Mär':\nWunder muss ich euch melden.\nVon des Wurmes Blut\nmir brannten die Finger;\nsie führt' ich kühlend zum Mund:\nkaum netzt' ein wenig\ndie Zunge das Nass, -\nwas da die Vöglein sangen,\ndas konnt' ich flugs verstehn.\nAuf den Ästen sass es und sang:\n\"Hei! Siegfried gehört nun\nder Niblungen Hort!\nOh! Fänd' in der Höhle\nden Hort er jetzt!\nWollt' er den Tarnhelm gewinnen,\nder taugt' ihm zu wonniger Tat!\nDoch möcht' er den Ring sich erraten,\nder macht ihn zum Walter der Welt!\"","translation":"Mime was the name of a grumpy dwarf:\nHe raised me under the compulsion of envy,\nthat once the child, when it had grown boldly,\na worm falls on him in the forest,\nThe lazy one there guards a hoard.\nHe taught me to forge metal and smelt ore;\nbut what the artist himself could not do,'\nThe apprentice's courage must succeed:\npieces of shattered steel\nto be reforged into a sword.\nI reconstructed my father's defense:\nI created Nothung for myself, nailed down.\nThe dwarf thought him fit for battle;\nthat led me to the forest:\nThere I fell Fafner, the worm.\nBut now pay attention to the tale:\nI have a miracle to report to you.\nFrom the worm's blood\nMy fingers were burning;\nI brought it to my mouth in a cooling manner:\nbarely nets a little\nthe tongue the wetness, -\nwhat the little birds were singing,\nI understood that immediately.\nIt sat on the branches and sang:\n\"Hey! Siegfried now belongs\nThe Nibelung hoard!\nOh! I found it in the cave.\nHe's in the daycare now!\nHe wanted to win the Tarnhelm,\nIt suited him for blissful deeds!\nBut he would like to guess the ring,\nThat makes him the Walter of the world!","literalText":true,"sourceStartIndex":72,"sourceLineCount":33},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Ring und Tarnhelm trugst du nun fort?","translation":"Have you now carried away the ring and the Tarnhelm?","literalText":true,"sourceStartIndex":105,"sourceLineCount":1},{"speaker":"DIE MANNEN","speakerTranslation":"DIE MANNEN","original":"Das Vöglein hörtest du wieder?","translation":"Did you hear the little bird again?","literalText":true,"sourceStartIndex":106,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Ring und Tarnhelm hatt' ich gerafft:\nda lauscht' ich wieder dem wonnigen Laller;\nder sass im Wipfel und sang:\n\"Hei, Siegfried gehört nun der Helm und der Ring.\nO traute er Mime, dem Treulosen, nicht!\nIhm sollt' er den Hort nur erheben;\nnun lauert er listig am Weg:\nnach dem Leben trachtet er Siegfried.\nOh, traute Siegfried nicht Mime!\"","translation":"I had got the ring and the Tarnhelm:\nThen I listened again to the delightful babbling;\nHe sat in the treetop and sang:\n\"Hey, Siegfried now owns the helmet and the ring.\"\nOh, he did not trust Mime, the faithless one!\nHe should only raise the hoard for him;\nNow he lurks cunningly by the roadside:\nHe seeks to kill Siegfried.\nOh, Siegfried didn't trust Mime!","literalText":true,"sourceStartIndex":107,"sourceLineCount":9},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Es mahnte dich gut?","translation":"Did it give you a good warning?","literalText":true,"sourceStartIndex":116,"sourceLineCount":1},{"speaker":"VIER MANNEN","speakerTranslation":"VIER MANNEN","original":"Vergaltest du Mime?","translation":"Did you pay Mime?","literalText":true,"sourceStartIndex":117,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Mit tödlichem Tranke trat er zu mir;\nbang und stotternd gestand er mir Böses:\nNotung streckte den Strolch!","translation":"He approached me carrying a deadly potion;\nAnxiously and stammeringly, he confessed evil things to me:\nNothung stretched the rascal!","literalText":true,"sourceStartIndex":118,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"grell lachend","translation":"laughing loudly","literalText":true,"sourceStartIndex":121,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Was er nicht geschmiedet,\nschmeckte doch Mime!","translation":"What he did not forge,\nMime tasted so good!","literalText":true,"sourceStartIndex":122,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"nacheinander","translation":"successively","literalText":true,"sourceStartIndex":124,"sourceLineCount":1},{"speaker":"ZWEI MANNEN","speakerTranslation":"ZWEI MANNEN","original":"Was wies das Vöglein dich wieder?","translation":"What did the little bird point out to you again?","literalText":true,"sourceStartIndex":125,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"lässt ein Trinkhorn neu füllen und träufelt den Saft eines Krautes hinein","translation":"He refills a drinking horn and drips the juice of an herb into it.","literalText":true,"sourceStartIndex":126,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Trink' erst, Held, aus meinem Horn:\nich würzte dir holden Trank,\ndie Erinnerung hell dir zu wecken,","translation":"First drink, hero, from my horn:\nI spiced your lovely potion,\nto brightly awaken your memory,","literalText":true,"sourceStartIndex":127,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"er reicht Siegfried das Horn","translation":"he hands Siegfried the horn","literalText":true,"sourceStartIndex":130,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"dass Fernes nicht dir entfalle!","translation":"that the distant future does not escape you!","literalText":true,"sourceStartIndex":131,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"blickt gedankenvoll in das Horn und trinkt dann langsam","translation":"gazes thoughtfully into the horn and then drinks slowly.","literalText":true,"sourceStartIndex":132,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"In Leid zu dem Wipfel lauscht' ich hinauf;\nda sass es noch und sang:\n\"Hei, Siegfried erschlug nun den schlimmen Zwerg!\nJetzt wüsst' ich ihm noch das herrlichste Weib.\nAuf hohem Felsen sie schläft,\nFeuer umbrennt ihren Saal;\ndurchschritt' er die Brunst,\nweckt' er die Braut -\nBrünnhilde wäre dann sein!\"","translation":"In sorrow I listened up to the treetop;\nThere it sat, still singing:\n\"Hey, Siegfried has now slain the wicked dwarf!\"\nNow I know the most wonderful woman for him.\nShe sleeps on a high rock,\nFire engulfs their hall;\nHe passed through the heat,\nHe wakes the bride -\nBrünnhilde would then be his!\"","literalText":true,"sourceStartIndex":133,"sourceLineCount":9},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Und folgtest du des Vögleins Rate?","translation":"And did you follow the little bird's advice?","literalText":true,"sourceStartIndex":142,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Rasch ohne Zögern zog ich nun aus,","translation":"I moved out quickly and without hesitation.","literalText":true,"sourceStartIndex":143,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Gunther hört mit wachsendem Erstaunen zu","translation":"Gunther listens with growing astonishment.","literalText":true,"sourceStartIndex":144,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"bis den feurigen Fels ich traf:","translatedTitle":"until I met the fiery rock:","participants":["SIEGFRIED","GUNTHER","HAGEN","VIER MANNEN","ZWEI ANDERE"],"sourceStartIndex":145,"sourceLineCount":40,"turns":[{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"bis den feurigen Fels ich traf:\ndie Lohe durchschritt ich\nund fand zum Lohn -","translation":"until I met the fiery rock:\nI walked through the flames\nand found his reward -","literalText":true,"sourceStartIndex":145,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"in immer grössere Verzückung geratend","translation":"falling into ever greater rapture","literalText":true,"sourceStartIndex":148,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"schlafend ein wonniges Weib\nin lichter Waffen Gewand.\nDen Helm löst' ich der herrlichen Maid;\nmein Kuss erweckte sie kühn:\noh, wie mich brünstig da umschlang\nder schönen Brünnhilde Arm!","translation":"sleeping, a blissful woman\nin light-colored armor.\nI removed the helmet from the beautiful maiden;\nMy kiss awakened her boldly:\nOh, how passionately he embraced me!\nThe beautiful Brünnhilde's arm!","literalText":true,"sourceStartIndex":149,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"in höchstem Schrecken aufspringend","translation":"jumping up in utter terror","literalText":true,"sourceStartIndex":155,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Was hör' ich!","translation":"What do I hear!","literalText":true,"sourceStartIndex":156,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Zwei Raben fliegen aus einem Busche auf, kreisen über Siegfried und fliegen dann, dem Rheine zu, davon","translation":"Two ravens fly up from a bush, circle above Siegfried, and then fly off towards the Rhine.","literalText":true,"sourceStartIndex":157,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Errätst du auch dieser Raben Geraun'?","translation":"Can you guess this raven's whisper?","literalText":true,"sourceStartIndex":158,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Siegfried fährt heftig auf und blickt, Hagen den Rücken zukehrend, den Raben nach","translation":"Siegfried jumped up violently and, turning his back on Hagen, looked after the ravens.","literalText":true,"sourceStartIndex":159,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":",\nRache rieten sie mir!","translation":",\nThey advised me to take revenge!","literalText":true,"sourceStartIndex":160,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er stösst seinen Speer in Siegfrieds Rücken: Gunther fällt ihm - zu spät - in den Arm. Siegfried schwingt mit beiden Händen seinen Schild hoch empor, um Hagen damit zu zerschmettern: die Kraft verlässt ihn, der Schild entsinkt ihm rückwärts; er selbst stürzt krachend über dem Schilde zusammen\nwelche vergebens Hagen zurückzuhalten versucht","translation":"He thrusts his spear into Siegfried's back: Gunther falls—too late—into his arms. Siegfried swings his shield high with both hands to shatter Hagen: his strength fails him, the shield falls backward from his grasp; he himself crashes down over the shield.\nwhich tries in vain to hold Hagen back","literalText":true,"sourceStartIndex":162,"sourceLineCount":2},{"speaker":"VIER MANNEN","speakerTranslation":"VIER MANNEN","original":"Hagen! Was tust du?","translation":"Hagen! What are you doing?","literalText":true,"sourceStartIndex":164,"sourceLineCount":1},{"speaker":"ZWEI ANDERE","speakerTranslation":"ZWEI ANDERE","original":"Was tatest du?","translation":"What did you do?","literalText":true,"sourceStartIndex":165,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Hagen, was tatest du?","translation":"Hagen, what did you do?","literalText":true,"sourceStartIndex":166,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"auf den zu Boden Gestreckten deutend","translation":"pointing at the man who was lying on the ground","literalText":true,"sourceStartIndex":167,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Meineid rächt' ich!","translation":"I'll avenge perjury!","literalText":true,"sourceStartIndex":168,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er wendet sich ruhig zur Seite ab und verliert sich dann einsam über die Höhe, wo man ihn langsam durch die bereits mit der Erscheinung der Raben eingebrochenen Dämmerung von dannen schreiten sieht. Gunther beugt sich schmerzergriffen zu Siegfrieds Seite nieder. Die Mannen umstehen teilnahmsvoll den Sterbenden\nvon zwei Mannen sitzend erhalten, schlägt die Augen glanzvoll auf","translation":"He calmly turns to the side and then disappears alone across the heights, where he can be seen slowly walking away through the twilight, which has already fallen with the appearance of the ravens. Gunther bends down, overcome with grief, at Siegfried's side. The men stand sympathetically around the dying man.\nReceived by two men sitting down, he opens his eyes brightly.","literalText":true,"sourceStartIndex":169,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Brünnhilde! Heilige Braut!\nWach' auf! Öffne dein Auge!\nWer verschloss dich wieder in Schlaf?\nWer band dich in Schlummer so bang?\nDer Wecker kam; er küsst dich wach,\nund aber - der Braut bricht er die Bande:\nda lacht ihm Brünnhildes Lust! -\nAch! Dieses Auge, ewig nun offen!\nAch, dieses Atems wonniges Wehen!\nSüsses Vergehen - seliges Grauen:\nBrünnhild' bietet mir - Gruss!","translation":"Brünnhilde! Holy Bride!\nWake up! Open your eyes!\nWho locked you away again, putting you back to sleep?\nWho bound you to sleep so anxiously?\nThe alarm clock came; it kisses you awake,\nand yet - he breaks the bride's bonds:\nBrünnhilde's delight laughs at him!\nAh! This eye, now forever open!\nAh, the blissful sighing of this breath!\nSweet transgression - blissful horror:\nBrünnhilde sends me greetings!","literalText":true,"sourceStartIndex":171,"sourceLineCount":11},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er sinkt zurück und stirbt. Regungslose Trauer der Umstehenden. Die Nacht ist hereingebrochen. Auf die stumme Ermahnung Gunthers erheben die Mannen Siegfrieds Leiche und geleiten mit dem Folgenden sie in feierlichem Zuge über die Felsenhöhe langsam von dannen. Gunther folgt der Leiche zunächst\nORCHESTERZWISCHENSPIEL\nTrauermusik beim Tode Siegfrieds. Der Mond bricht durch die Wolken hervor und beleuchtet immer heller den die Berghöhe erreichenden Trauerzug. Dann steigen Nebel aus dem Rheine auf und erfüllen allmählich die ganze Bühne, auf welcher der Trauerzug bereits unsichtbar geworden ist, bis nach vorne, so dass diese während des Zwischenspiels gänzlich verhüllt bleibt. Als sich die Nebel wieder verteilen, tritt die Halle der Gibichungen, wie im ersten Aufzuge, immer erkennbarer hervor","translation":"He sinks back and dies. The onlookers are filled with motionless grief. Night has fallen. At Gunther's silent admonition, the men raise Siegfried's body and, together with those who follow, solemnly escort it slowly away over the rocky ridge. Gunther initially follows the body.\nORCHESTRA INTERLUDE\nFuneral music at Siegfried's death. The moon breaks through the clouds and illuminates the funeral procession, which reaches the mountaintop, ever more brightly. Then mists rise from the Rhine and gradually fill the entire stage, on which the funeral procession has already become invisible, all the way to the front, so that it remains completely shrouded during the interlude. As the mists dissipate, the Gibichung hall, as in the first act, becomes increasingly recognizable.","literalText":true,"sourceStartIndex":182,"sourceLineCount":3}]}]},{"number":4,"originalHeading":"DRITTE SZENE","translatedHeading":"Fourth Scene","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"War das sein Horn?","translatedTitle":"Was that his horn?","participants":["GUTRUNE","HAGENS STIMME","HAGEN","GUNTHER"],"sourceStartIndex":0,"sourceLineCount":74,"turns":[{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"War das sein Horn?","translation":"Was that his horn?","literalText":true,"sourceStartIndex":0,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie lauscht","translation":"She listens","literalText":true,"sourceStartIndex":1,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Nein! - Noch kehrt er nicht heim. -\nSchlimme Träume störten mir den Schlaf!\nWild wieherte sein Ross;\nLachen Brünnhildes weckte mich auf.\nWer war das Weib,\ndas ich zum Ufer schreiten sah?\nIch fürchte Brünnhild'!\nIst sie daheim?","translation":"No! - He's not returning home yet.\nBad dreams were disturbing my sleep!\nHis horse neighed wildly;\nBrünnhilde's laughter woke me up.\nWho was the woman?\nthat I saw myself walking towards the shore?\nI fear Brünnhilde!\nIs she at home?","literalText":true,"sourceStartIndex":2,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie lauscht an der Tür rechts und ruft dann leise","translation":"She listens at the door on the right and then calls out softly.","literalText":true,"sourceStartIndex":10,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Brünnhild'! Brünnhild'!\nBist du wach?","translation":"Brünnhild'! Brünnhild'!\nAre you awake?","literalText":true,"sourceStartIndex":11,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie öffnet schüchtern und blickt in das innere Gemach","translation":"She opens the door shyly and looks into the inner chamber.","literalText":true,"sourceStartIndex":13,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Leer das Gemach.\nSo war es sie,\ndie ich zum Rheine schreiten sah!","translation":"Empty the room.\nThat was her,\nwhom I saw walking towards the Rhine!","literalText":true,"sourceStartIndex":14,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie erschrickt und lauscht nach der Ferne","translation":"She is startled and listens for the distant sound.","literalText":true,"sourceStartIndex":17,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"War das sein Horn?\nNein! - Öd' alles!\nSäh' ich Siegfried nur bald!","translation":"Was that his horn?\nNo! - Everything's boring!\nIf only I could see Siegfried soon!","literalText":true,"sourceStartIndex":18,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie will sich wieder ihrem Gemache zuwenden: als sie jedoch Hagens Stimme vernimmt, hält sie an und bleibt, von Furcht gefesselt, eine Zeitlang unbeweglich stehen\nvon aussen sich nähernd","translation":"She wants to return to her chamber; however, when she hears Hagen's voice, she stops and, gripped by fear, remains motionless for a while.\napproaching from the outside","literalText":true,"sourceStartIndex":21,"sourceLineCount":2},{"speaker":"HAGENS STIMME","speakerTranslation":"HAGENS STIMME","original":"Hoiho! Hoiho!\nWacht auf! Wacht auf!\nLichte! Lichte! Helle Brände!\nJagdbeute bringen wir heim.\nHoiho! Hoiho!","translation":"Hoiho! Hoiho!\nWake up! Wake up!\nLights! Lights! Bright fires!\nWe bring home our hunting spoils.\nHoiho! Hoiho!","literalText":true,"sourceStartIndex":23,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Licht und wachsender Feuerschein von aussen\ntritt in die Halle","translation":"Light and growing firelight from outside\nenters the hall","literalText":true,"sourceStartIndex":28,"sourceLineCount":2},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Auf, Gutrun'! Begrüsse Siegfried!\nDer starke Held, er kehret heim!","translation":"Up, Gutrun! Greet Siegfried!\nThe mighty hero, he returns home!","literalText":true,"sourceStartIndex":30,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"im grosser Angst","translation":"in great fear","literalText":true,"sourceStartIndex":32,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Was geschah? Hagen!\nNicht hört' ich sein Horn!","translation":"What happened? Hagen!\nI did not hear his horn!","literalText":true,"sourceStartIndex":33,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Männer und Frauen, mit Lichtern und Feuerbränden, geleiten den Zug der mit Siegfrieds Leiche Heimkehrenden, unter denen Gunther","translation":"Men and women, with lights and fires, escort the procession of those returning home with Siegfried's body, among whom is Gunther.","literalText":true,"sourceStartIndex":35,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Der bleiche Held,\nnicht bläst er es mehr;\nnicht stürmt er zur Jagd,\nzum Streite nicht mehr,\nnoch wirbt er um wonnige Frauen.","translation":"The pale hero,\nHe doesn't blow it anymore;\nHe does not rush off to hunt,\nno more arguments,\nHe is still courting blissful women.","literalText":true,"sourceStartIndex":36,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"mit wachsendem Entsetzen","translation":"with growing horror","literalText":true,"sourceStartIndex":41,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Was bringen die?","translation":"What do they do?","literalText":true,"sourceStartIndex":42,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Der Zug gelangt in die Mitte der Halle, und die Mannen setzen dort die Leiche auf einer schnell errichteten Erhöhung nieder","translation":"The train reaches the middle of the hall, and the men place the body on a hastily erected platform.","literalText":true,"sourceStartIndex":43,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Eines wilden Ebers Beute:\nSiegfried, deinen toten Mann.","translation":"Prey of a wild boar:\nSiegfried, your dead husband.","literalText":true,"sourceStartIndex":44,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Gutrune schreit auf und stürzt über die Leiche hin. Allgemeine Erschütterung und Trauer\nbemüht sich um die Ohnmächtige","translation":"Gutrune screams and falls over the corpse. General shock and grief.\ntries to help the powerless one","literalText":true,"sourceStartIndex":46,"sourceLineCount":2},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Gutrun'! Holde Schwester,\nhebe dein Auge, schweige mir nicht!","translation":"Gutrun! Dear sister,\nLift up your eye, do not be silent to me!","literalText":true,"sourceStartIndex":48,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"wieder zu sich kommend","translation":"regaining consciousness","literalText":true,"sourceStartIndex":50,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Siegfried - Siegfried erschlagen!","translation":"Siegfried - Siegfried slain!","literalText":true,"sourceStartIndex":51,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie stösst Gunther heftig zurück","translation":"She pushes Gunther away violently.","literalText":true,"sourceStartIndex":52,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Fort, treuloser Bruder,\ndu Mörder meines Mannes!\nO Hilfe! Hilfe! Wehe! Wehe!\nSie haben Siegfried erschlagen!","translation":"Away, faithless brother,\nYou murderer of my husband!\nOh help! Help! Woe! Woe!\nThey killed Siegfried!","literalText":true,"sourceStartIndex":53,"sourceLineCount":4},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Nicht klage wider mich!\nDort klage wider Hagen.\nEr ist der verfluchte Eber,\nder diesen Edlen zerfleischt'.","translation":"Don't sue me!\nThere, he filed a lawsuit against Hagen.\nHe is the cursed boar,\nwho tears this noble man to pieces'.","literalText":true,"sourceStartIndex":57,"sourceLineCount":4},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Bist du mir gram darum?","translation":"Are you angry with me for that?","literalText":true,"sourceStartIndex":61,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Angst und Unheil greife dich immer!","translation":"Fear and misfortune always seize you!","literalText":true,"sourceStartIndex":62,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"mit furchtbarem Trotze herantretend","translation":"approaching with terrible defiance","literalText":true,"sourceStartIndex":63,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Ja denn! Ich hab' ihn erschlagen!\nIch - Hagen - schlug ihn zu Tod.\nMeinem Speer war er gespart,\nbei dem er Meineid sprach.\nHeiliges Beuterecht\nhab' ich mir nun errungen:\ndrum fordr' ich hier diesen Ring.","translation":"Well then! I killed him!\nI – Hagen – beat him to death.\nMy spear was spared it,\nduring which he committed perjury.\nSacred booty law\nI have now achieved this:\nTherefore, I demand this ring here.","literalText":true,"sourceStartIndex":64,"sourceLineCount":7},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Zurück! Was mir verfiel,\nsollst nimmer du empfahn.","translation":"Back! What I had lost,\nYou shall never receive.","literalText":true,"sourceStartIndex":71,"sourceLineCount":2},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Ihr Mannen, richtet mein Recht!","translation":"You men, administer my justice!","literalText":true,"sourceStartIndex":73,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Rührst du an Gutrunes Erbe,","translatedTitle":"If you touch Gutrune's legacy,","participants":["GUNTHER","HAGEN","BRÜNNHILDE","GUTRUNE"],"sourceStartIndex":74,"sourceLineCount":62,"turns":[{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Rührst du an Gutrunes Erbe,\nschamloser Albensohn?","translation":"If you touch Gutrune's legacy,\nShameless son of an elves?","literalText":true,"sourceStartIndex":74,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"sein Schwert ziehend","translation":"drawing his sword","literalText":true,"sourceStartIndex":76,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Des Alben Erbe fordert so sein Sohn!","translation":"The Alb's heir is thus claimed by his son!","literalText":true,"sourceStartIndex":77,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er dringt auf Gunther ein, dieser wehrt sich; sie fechten. Die Mannen werfen sich dazwischen. Gunther fällt von einem Streiche Hagens darnieder","translation":"He attacks Gunther, who defends himself; they fight. The men throw themselves between them. Gunther falls from one of Hagen's blows.","literalText":true,"sourceStartIndex":78,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Her den Ring!","translation":"Give me the ring!","literalText":true,"sourceStartIndex":79,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er greift nach Siegfrieds Hand; diese hebt sich drohend empor. Gutrune und die Frauen schreien entsetzt laut auf. Alles bleibt in Schauder regungslos gefesselt. Vom Hintergrunde her schreitet Brünnhilde fest und feierlich dem Vordergrunde zu\nnoch im Hintergrunde","translation":"He reaches for Siegfried's hand; it rises menacingly. Gutrune and the women cry out in horror. All remain frozen in a shudder. From the background, Brünnhilde strides firmly and solemnly toward the foreground.\nstill in the background","literalText":true,"sourceStartIndex":80,"sourceLineCount":2},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Schweigt eures Jammers\njauchzenden Schwall!\nDas ihr alle verrietet,\nzur Rache schreitet sein Weib.","translation":"Silence your lament\na jubilant outburst!\nThat you all betrayed,\nHis wife takes revenge.","literalText":true,"sourceStartIndex":82,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie schreitet ruhig weiter vor","translation":"She continues walking calmly.","literalText":true,"sourceStartIndex":86,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Kinder hört' ich greinen nach der Mutter,\nda süsse Milch sie verschüttet:\ndoch nicht erklang mir würdige Klage,\ndes hehrsten Helden wert.","translation":"I heard children crying for their mother,\nbecause she spilled sweet milk:\nBut no worthy lament was heard from me,\nworthy of the noblest hero.","literalText":true,"sourceStartIndex":87,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"vom Boden heftig sich aufrichtend","translation":"violently rising from the ground","literalText":true,"sourceStartIndex":91,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Brünnhilde! Neiderboste!\nDu brachtest uns diese Not:\ndie du die Männer ihm verhetztest,\nweh, dass du dem Haus genaht!","translation":"Brünnhilde! Envious bastards!\nYou brought us this hardship:\nthat you incited the men against him,\nWoe betide you for approaching the house!","literalText":true,"sourceStartIndex":92,"sourceLineCount":4},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Armselige, schweig'!\nSein Eheweib warst du nie,\nals Buhlerin bandest du ihn.\nSein Mannesgemahl bin ich,\nder ewige Eide er schwur,\neh' Siegfried je dich ersah.","translation":"Wretched people, be silent!\nYou were never his wife,\nYou bound him as his lover.\nI am his husband,\nhe swore an eternal oath,\nbefore Siegfried ever saw you.","literalText":true,"sourceStartIndex":96,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"in jähe Verzweiflung ausbrechend","translation":"breaking out into sudden despair","literalText":true,"sourceStartIndex":102,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Verfluchter Hagen!\nDass du das Gift mir rietest,\ndas ihr den Gatten entrückt!\nAch, Jammer!\nWie jäh nun weiss ich's,\nBrünnhilde war die Traute,\ndie durch den Trank er vergass! -","translation":"Damn Hagen!\nThat you advised me to use the poison,\nthat you may steal your husband away!\nOh, what a shame!\nHow suddenly I now know,\nBrünnhilde was the darling,\nwhich he forgot because of the drink!","literalText":true,"sourceStartIndex":103,"sourceLineCount":7},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie wendet sich voll Scheu von Siegfried ab und beugt sich, im Schmerz aufgelöst, über Gunthers Leiche; so verbleibt sie regungslos bis zum Ende. Hagen steht, trotzig auf Speer und Schild gelehnt, in finsteres Sinnen versunken, auf der entgegengesetzen Seite\nallein in der Mitte; nachdem sie lange, zuerst mit tiefer Erschütterung, dann mit fast überwältigender Wehmut das Angesicht Siegfrieds betrachtet, wendet sie sich mit feierlicher Erhebung an die Männer und Frauen. Zu den Mannen","translation":"She turns away from Siegfried in utter fear and, consumed by grief, bends over Gunther's corpse; thus she remains motionless until the end. Hagen stands defiantly leaning on his spear and shield, lost in dark thoughts, on the opposite side.\nAlone in the center; after gazing at Siegfried's face for a long time, first with profound shock, then with almost overwhelming melancholy, she turns with solemn elevation to the men and women. To the men","literalText":true,"sourceStartIndex":110,"sourceLineCount":2},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Starke Scheite schichtet mir dort\nam Rande des Rheins zuhauf!\nHoch und hell lodre die Glut,\ndie den edlen Leib\ndes hehrsten Helden verzehrt.\nSein Ross führet daher,\ndass mit mir dem Recken es folge:\ndenn des Helden heiligste Ehre zu teilen,\nverlangt mein eigener Leib.\nVollbringt Brünnhildes Wunsch!","translation":"Stack some thick logs there for me\nPlenty along the banks of the Rhine!\nHigh and bright, the embers blaze,\nwho the noble body\nconsumed by the noblest hero.\nHis horse therefore leads,\nthat it would follow me, the hero:\nfor to share the hero's most sacred honor,\nMy own body demands it.\nFulfill Brünnhilde's wish!","literalText":true,"sourceStartIndex":112,"sourceLineCount":10},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Die jüngeren Männer errichten während des Folgenden vor der Halle nahe am Rheinufer einen mächtigen Scheiterhaufen, Frauen schmücken ihn mit Decken, auf die sie Kräuter und Blumen streuen\nversinkt von neuem in die Betrachtung des Antlitzes der Leiche Siegfrieds. Ihre Mienen nehmen eine immer sanftere Verklärung an","translation":"During the following events, the younger men erect a mighty pyre in front of the hall near the banks of the Rhine; women decorate it with blankets onto which they scatter herbs and flowers.\nShe sinks once more into contemplating the face of Siegfried's corpse. Her expression takes on an ever gentler transfiguration.","literalText":true,"sourceStartIndex":122,"sourceLineCount":2},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Wie Sonne lauter strahlt mir sein Licht:\nder Reinste war er, der mich verriet!\nDie Gattin trügend, - treu dem Freunde, -\nvon der eignen Trauten - einzig ihm teuer -\nschied er sich durch sein Schwert.\nEchter als er schwur keiner Eide;\ntreuer als er hielt keiner Verträge;\nlautrer als er liebte kein andrer:\nund doch, alle Eide, alle Verträge,\ndie treueste Liebe trog keiner wie er! -\nWisst ihr, wie das ward?","translation":"His light shines on me like the sun shines brighter:\nHe was the purest one, the one who betrayed me!\nDeceiving his wife, - faithful to his friend, -\nof his own timidity - only he is dear to his heart -\nHe separated himself with his sword.\nNo one swore oaths more genuinely than he did;\nNo one kept contracts more faithfully than he did;\nNo one loved more purely than he did:\nAnd yet, all oaths, all contracts,\nNo one could deceive the most faithful love like he did!\nDo you know what that was like?","literalText":true,"sourceStartIndex":124,"sourceLineCount":11},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"nach oben blickend","translation":"looking upwards","literalText":true,"sourceStartIndex":135,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"O ihr, der Eide ewige Hüter!","translatedTitle":"O you who are eternal keepers of oaths!","participants":["BRÜNNHILDE","HAGEN"],"sourceStartIndex":136,"sourceLineCount":61,"turns":[{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"O ihr, der Eide ewige Hüter!\nLenkt euren Blick auf mein blühendes Leid:\nerschaut eure ewige Schuld!\nMeine Klage hör', du hehrster Gott!\nDurch seine tapferste Tat,\ndir so tauglich erwünscht,\nweihtest du den, der sie gewirkt,\ndem Fluche, dem du verfielest:\nmich musste der Reinste verraten,\ndass wissend würde ein Weib!\nWeiss ich nun, was dir frommt? -\nAlles, alles, alles weiss ich,\nalles ward mir nun frei!\nAuch deine Raben hör' ich rauschen;\nmit bang ersehnter Botschaft\nsend' ich die beiden nun heim.\nRuhe, ruhe, du Gott! -","translation":"O you who are eternal keepers of oaths!\nTurn your gaze to my blossoming suffering:\nBehold your eternal guilt!\nHear my lament, O most exalted God!\nThrough his bravest act,\nDesired to be as suitable as possible for you,\nDid you dedicate the one who made them?\nthe curse you fell under:\nThe Purest One had to betray me\nThat knowing would make a woman!\nDo I now know what is good for you?\nI know everything, everything, everything.\nEverything was now free for me!\nI can hear your ravens rustling too;\nwith eagerly awaited message\nI'm sending them both home now.\nRest, rest, O God!","literalText":true,"sourceStartIndex":136,"sourceLineCount":17},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie winkt den Mannen, Siegfrieds Leiche auf den Scheiterhaufen zu tragen; zugleich zieht sie von Siegfrieds Finger den Ring ab und betrachtet ihn sinnend","translation":"She beckons the men to carry Siegfried's body to the pyre; at the same time, she removes the ring from Siegfried's finger and gazes at it thoughtfully.","literalText":true,"sourceStartIndex":153,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Mein Erbe nun nehm' ich zu eigen.\nVerfluchter Reif! Furchtbarer Ring!\nDein Gold fass' ich und geb' es nun fort.\nDer Wassertiefe weise Schwestern,\ndes Rheines schwimmende Töchter,\neuch dank' ich redlichen Rat.\nWas ihr begehrt, ich geb' es euch:\naus meiner Asche nehmt es zu eigen!\nDas Feuer, das mich verbrennt,\nrein'ge vom Fluche den Ring!\nIhr in der Flut löset ihn auf,\nund lauter bewahrt das lichte Gold,\ndas euch zum Unheil geraubt.","translation":"I now take possession of my inheritance.\nCursed hoop! Dreadful ring!\nI gather your gold and now give it away.\nThe wise sisters of the deep water,\ndaughters of the Rhine,\nI thank you for your honest advice.\nWhatever you desire, I will give it to you:\nFrom my ashes, claim it as your own!\nThe fire that is burning me,\nClean the ring of the curse!\nYou dissolve it in the flood,\nand the bright gold is preserved by louder\nthat has robbed you of your misfortune.","literalText":true,"sourceStartIndex":154,"sourceLineCount":13},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie hat sich den Ring angesteckt und wendet sich jetzt zu dem Scheiterhaufen, auf welchem Siegfrieds Leiche ausgestreckt liegt. Sie entreisst einem Manne den mächtigen Feuerbrand, schwingt diesen und deutet nach dem Hintergrunde","translation":"She put on the ring and now turns to the funeral pyre on which Siegfried's body lies stretched out. She snatches the mighty firebrand from a man, brandishes it, and points towards the background.","literalText":true,"sourceStartIndex":167,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Fliegt heim, ihr Raben!\nRaunt es eurem Herren,\nwas hier am Rhein ihr gehört!\nAn Brünnhildes Felsen fahrt vorbei! -\nDer dort noch lodert,\nweiset Loge nach Walhall!\nDenn der Götter Ende dämmert nun auf.\nSo - werf' ich den Brand\nin Walhalls prangende Burg.","translation":"Fly home, you ravens!\nWhisper it to your lord,\nwhat belongs to you here on the Rhine!\nPass by Brünnhilde's rock!\nThe one that is still burning there,\npoints the lodge to Valhalla!\nFor the end of the gods is now dawning.\nSo - I'll start the fire\nin Valhalla's magnificent castle.","literalText":true,"sourceStartIndex":168,"sourceLineCount":9},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie schleudert den Brand in den Holzstoss, der sich schnell hell entzündet. Zwei Raben sind vom Felsen am Ufer aufgeflogen und verschwinden nach den Hintergrunde zu. Brünnhilde gewahrt ihr Ross, welches zwei junge Männer hereinführen. Sie ist ihm entgegengesprungen, fasst es und entzäumt es schnell; dann neigt sie sich traulich zu ihm","translation":"She hurls the fire into the woodpile, which quickly bursts into bright flames. Two ravens have flown from the rocks on the shore and disappear into the distance. Brünnhilde notices her horse, which two young men are leading in. She leaps towards it, seizes it, and quickly unbridles it; then she leans affectionately towards it.","literalText":true,"sourceStartIndex":177,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Grane, mein Ross!\nSei mir gegrüsst!\nWeisst du auch, mein Freund,\nwohin ich dich führe?\nIm Feuer leuchtend, liegt dort dein Herr,\nSiegfried, mein seliger Held.\nDem Freunde zu folgen, wieherst du freudig?\nLockt dich zu ihm die lachende Lohe?\nFühl' meine Brust auch, wie sie entbrennt;\nhelles Feuer das Herz mir erfasst,\nihn zu umschlingen, umschlossen von ihm,\nin mächtigster Minne vermählt ihm zu sein!\nHeiajoho! Grane!\nGrüss' deinen Herren!\nSiegfried! Siegfried! Sieh!\nSelig grüsst dich dein Weib!","translation":"Grane, my horse!\nGreetings!\nDo you also know, my friend,\nwhere am I taking you?\nShining in the fire, there lies your Lord,\nSiegfried, my blessed hero.\nFollowing your friend, do you neigh joyfully?\nDoes the laughing flame lure you to him?\nFeel my breast burning too;\nbright fire seizes my heart,\nto embrace him, to be enclosed by him,\nTo be wedded to him in the most powerful love!\nHeiajoho! Grane!\nSay hello to your master!\nSiegfried! Siegfried! Look!\nYour wife sends you her warmest greetings!","literalText":true,"sourceStartIndex":178,"sourceLineCount":16},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie hat sich auf das Ross geschwungen und hebt es jetzt zum Sprunge. Sie sprengt es mit einem Satze in den brennenden Scheiterhaufen. Sogleich steigt prasselnd der Brand hoch auf, so dass das Feuer den ganzen Raum vor der Halle erfüllt und diese selbst schon zu ergreifen scheint. Entsetzt drängen sich Männer und Frauen nach dem äussersten Vordergrunde. Als der ganze Bühnenraum nur noch von Feuer erfüllt erscheint, verlischt plötzlich der Glutschein, so dass bald bloss ein Dampfgewölk zurückbleibt, welches sich dem Hintergrunde zu verzieht und dort am Horizont sich als finstere Wolkenschicht lagert. Zugleich ist vom Ufer her der Rhein mächtig angeschwollen und hat seine Flut über die Brandstätte gewälzt. Auf den Wogen sind die drei Rheintöchter herbeigeschwommen und erscheinen jetzt über der Brandstätte. Hagen, der seit dem Vorgange mit dem Ringe Brünnhildes Benehmen mit wachsender Angst beobachtet hat, gerät beim Anblick der Rheintöchter in höchsten Schreck. Er wirft hastig Speer, Schild und Helm von sich und stürzt wie wahnsinnig sich in die Flut","translation":"She has swung herself onto the horse and now lifts it to leap. With a single bound, she sends it hurtling into the burning pyre. Immediately, the flames rise with a crackling roar, so that the fire fills the entire space in front of the hall and seems to be encroaching upon it. Terrified, men and women crowd toward the far foreground. When the entire stage appears filled only with fire, the glow of the embers suddenly disappears, leaving behind only a wisp of steam, which drifts toward the background and settles there on the horizon as a dark layer of clouds. At the same time, the Rhine has swelled mightily from its banks and has washed its flood over the blaze. On the waves, the three Rhine maidens have swum toward and now appear above the burning site. Hagen, who since the incident with the ring has observed Brünnhilde's behavior with growing fear, is seized with utter terror at the sight of the Rhine maidens. He hastily throws away his spear, shield, and helmet and plunges into the flood like a madman.","literalText":true,"sourceStartIndex":194,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Zurück vom Ring!","translation":"Back from the ring!","literalText":true,"sourceStartIndex":195,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Woglinde und Wellgunde umschlingen mit ihren Armen seinen Nacken und ziehen ihn so, zurückschwimmend, mit sich in die Tiefe. Flosshilde, den anderen voran dem Hintergrunde zuschwimmend, hält jubelnd den gewonnenen Ring in die Höhe. Durch die Wolkenschicht, welche sich am Horizont gelagert, bricht ein rötlicher Glutschein mit wachsender Helligkeit aus. Von dieser Helligkeit beleuchtet, sieht man die drei Rheintöchter auf den ruhigeren Wellen des allmählich wieder in sein Bett zurückgetretenen Rheines, lustig mit dem Ringe spielend, im Reigen schwimmen. Aus den Trümmern der zusammengestürzten Halle sehen die Männer und Frauen in höchster Ergriffenheit dem wachsenden Feuerschein am Himmel zu. Als dieser endlich in lichtester Helligkeit leuchtet, erblickt man darin den Saal Walhalls, in welchem die Götter und Helden, ganz nach der Schilderung Waltrautes im ersten Aufzuge, versammelt sitzen. Helle Flammen scheinen in dem Saal der Götter aufzuschlagen. Als die Götter von den Flammen gänzlich verhüllt sind, fällt der Vorhang","translation":"Woglinde and Wellgunde encircle his neck with their arms and, swimming backward, pull him with them into the depths. Flosshilde, swimming ahead of the others toward the background, jubilantly holds the ring she has won aloft. Through the layer of clouds that has settled on the horizon, a reddish glow erupts, growing ever brighter. Illuminated by this light, the three Rhine maidens can be seen swimming in a circle on the calmer waves of the Rhine, which has gradually returned to its bed, playfully toying with the ring. From the ruins of the collapsed hall, the men and women gaze in profound emotion at the growing blaze in the sky. When it finally shines with the brightest light, the hall of Valhalla is revealed, where the gods and heroes sit gathered, just as Waltraute described in the first act. Bright flames seem to leap into the hall of the gods. When the gods are completely enveloped by the flames, the curtain falls.","literalText":true,"sourceStartIndex":196,"sourceLineCount":1}]}]}];
